import math

def ncdf(x):
    return 0.5 * (1 + math.erf(x / math.sqrt(2)))

def npdf(x):
    return math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)

S, K, r, T, C = 100, 100, 0.05, 1.0, 10.4506
sig = 0.5
for _ in range(3):
    d1 = (math.log(S / K) + (r + 0.5 * sig * sig) * T) / (sig * math.sqrt(T))
    price = S * ncdf(d1) - K * math.exp(-r * T) * ncdf(d1 - sig * math.sqrt(T))
    vega = S * math.sqrt(T) * npdf(d1)
    sig -= (price - C) / vega
print(round(sig, 4))
